import Mathlib

/-!
# Piecewise-Linear Functions and ReLU Network Region Bounds

This file formalizes the connection between ReLU neural networks and piecewise-linear
(PWL) functions, and proves the fundamental bound on the number of linear regions of a
single hidden layer ReLU network (a form of **Schläfli's hyperplane-arrangement bound**).

We work over `ℝ^n = (Fin n → ℝ)`.  An *affine functional* is given by a pair
`(a, b) : (Fin n → ℝ) × ℝ` and evaluates to `⟨a, x⟩ + b`.

## Main results

* `relu_pwl` (**Theorem 1**): `x ↦ relu (⟨a,x⟩ + b)` is piecewise linear with two
  linear regions — an open convex region `{x : ⟨a,x⟩+b > 0}` on which it equals
  `⟨a,x⟩+b`, and an open convex region `{x : ⟨a,x⟩+b < 0}` on which it equals `0` — and
  it is continuous.

* `region_count_bound` (**Theorem 2, Schläfli's bound**): a hyperplane arrangement of
  `w` hyperplanes in `ℝ^n` has at most `∑_{k=0}^{min n w} C(w,k)` regions, where a region
  is a connected component of the complement of the union of the hyperplanes (counted
  here by its sign vector, the standard combinatorial chamber count).

* `single_layer_region_bound` (**Theorem 3**): a single hidden layer ReLU network of
  width `w` is affine on each chamber of the arrangement of its `w` neuron hyperplanes,
  and the number of its linear regions is at most `∑_{k=0}^{min n w} C(w,k)`.

The proof of Schläfli's bound goes through **VC dimension** and the **Sauer–Shelah
lemma** (`Finset.card_shatterer_le_sum_vcDim`): the family of realizable sign vectors of
an arrangement of `w` affine functionals on `ℝ^n` has VC dimension at most `n`, because
`n+1` affine functionals on `ℝ^n` are linearly dependent (together with the constant
`1`), hence their values lie in an affine hyperplane of `ℝ^{n+1}`, which cannot meet all
`2^{n+1}` open orthants.
-/

namespace ReLURegions

open Finset

/-! ### ReLU activation -/

/-- The ReLU activation function `relu x = max 0 x`. -/
def relu (x : ℝ) : ℝ := max 0 x

@[simp] lemma relu_nonneg (x : ℝ) : 0 ≤ relu x := le_max_left _ _

lemma relu_eq_self {x : ℝ} (hx : 0 ≤ x) : relu x = x := max_eq_right hx

lemma relu_of_pos {x : ℝ} (hx : 0 < x) : relu x = x := max_eq_right hx.le

lemma relu_of_nonpos {x : ℝ} (hx : x ≤ 0) : relu x = 0 := max_eq_left hx

lemma relu_continuous : Continuous relu := continuous_const.max continuous_id

/-- Coordinatewise ReLU on `ℝ^w`. -/
def reluVec {w : ℕ} (v : Fin w → ℝ) : Fin w → ℝ := fun i => relu (v i)

/-! ### Affine functionals on `ℝ^n` -/

/-- Evaluate the affine functional `(a, b)` at `x`, giving `⟨a, x⟩ + b`. -/
def affEval {n : ℕ} (p : (Fin n → ℝ) × ℝ) (x : Fin n → ℝ) : ℝ :=
  (∑ i, p.1 i * x i) + p.2

lemma affEval_continuous {n : ℕ} (p : (Fin n → ℝ) × ℝ) : Continuous (affEval p) := by
  unfold affEval
  exact (continuous_finset_sum _ (fun i _ => continuous_const.mul (continuous_apply i))).add
    continuous_const

/-! ### Theorem 1 : ReLU of an affine functional is piecewise linear -/

/-
**Theorem 1 (ReLU is PWL).**  For any affine functional `(a,b)` on `ℝ^n`, the
function `x ↦ relu (⟨a,x⟩ + b)` is piecewise linear with exactly two linear regions:

* on the open, convex region `{x : ⟨a,x⟩+b > 0}` it equals the affine map `⟨a,x⟩+b`;
* on the open, convex region `{x : ⟨a,x⟩+b < 0}` it equals `0`;

and it is globally continuous.
-/
theorem relu_pwl {n : ℕ} (p : (Fin n → ℝ) × ℝ) :
    (∀ x, 0 < affEval p x → relu (affEval p x) = affEval p x) ∧
    (∀ x, affEval p x < 0 → relu (affEval p x) = 0) ∧
    Continuous (fun x => relu (affEval p x)) ∧
    IsOpen {x | 0 < affEval p x} ∧ IsOpen {x | affEval p x < 0} ∧
    Convex ℝ {x | 0 < affEval p x} ∧ Convex ℝ {x | affEval p x < 0} := by
  refine' ⟨ fun x hx => relu_of_pos hx, fun x hx => relu_of_nonpos ( le_of_lt hx ), _, _, _, _, _ ⟩;
  · exact relu_continuous.comp ( affEval_continuous p );
  · exact isOpen_lt continuous_const ( affEval_continuous p );
  · exact isOpen_lt ( affEval_continuous p ) continuous_const;
  · refine' convex_iff_forall_pos.mpr _;
    intro x hx y hy a b ha hb hab; simp_all +decide [ affEval ] ;
    simp_all +decide [ mul_add, mul_left_comm, Finset.sum_add_distrib ];
    rw [ ← Finset.mul_sum _ _ _, ← Finset.mul_sum _ _ _ ] ; rw [ ← eq_sub_iff_add_eq' ] at hab ; subst_vars ; nlinarith;
  · unfold affEval;
    refine' convex_iff_forall_pos.mpr _;
    simp +decide [ mul_add, Finset.sum_add_distrib, mul_left_comm ];
    intro x hx y hy a b ha hb hab; rw [ ← Finset.mul_sum _ _ _, ← Finset.mul_sum _ _ _ ] ; rw [ ← eq_sub_iff_add_eq' ] at hab; subst hab; nlinarith;

/-! ### Hyperplane arrangements and their region count -/

/-- A hyperplane arrangement of `w` hyperplanes in `ℝ^n`: each index gives a normal
vector and an offset, defining the affine functional `⟨a_i, x⟩ + b_i` whose zero set is
the `i`-th hyperplane. -/
def Arrangement (n w : ℕ) := Fin w → (Fin n → ℝ) × ℝ

/-- The set of indices `i` whose affine functional is strictly positive at `x`. -/
noncomputable def posSet {n w : ℕ} (H : Arrangement n w) (x : Fin n → ℝ) : Finset (Fin w) :=
  Finset.univ.filter (fun i => 0 < affEval (H i) x)

lemma mem_posSet {n w : ℕ} (H : Arrangement n w) (x : Fin n → ℝ) (i : Fin w) :
    i ∈ posSet H x ↔ 0 < affEval (H i) x := by
  simp [posSet]

open scoped Classical in
/-- The family of realizable sign vectors of an arrangement, i.e. the sets
`{i : ⟨a_i,x⟩+b_i > 0}` for points `x` lying in the *complement* of the union of the
hyperplanes (where every functional is nonzero).  These index exactly the connected
components (chambers) of the complement. -/
noncomputable def regionFamily {n w : ℕ} (H : Arrangement n w) : Finset (Finset (Fin w)) :=
  Finset.univ.filter (fun S => ∃ x, (∀ i, affEval (H i) x ≠ 0) ∧ posSet H x = S)

open scoped Classical in
lemma mem_regionFamily {n w : ℕ} (H : Arrangement n w) (S : Finset (Fin w)) :
    S ∈ regionFamily H ↔ ∃ x, (∀ i, affEval (H i) x ≠ 0) ∧ posSet H x = S := by
  simp [regionFamily]

/-- The number of regions (chambers) of a hyperplane arrangement: the number of
connected components of the complement of the union of the hyperplanes, counted by their
sign vectors. -/
noncomputable def RegionCount {n w : ℕ} (H : Arrangement n w) : ℕ :=
  (regionFamily H).card

/-! ### Linear dependence of `n+1` affine functionals -/

/-
**Linear dependence.**  Any `n+1` (or more) affine functionals on `ℝ^n` admit a
nontrivial linear combination, supported on the index set `T`, that is constant (its
linear part vanishes).  Concretely there is `c : Fin w → ℝ` supported on `T`, not
identically zero on `T`, with vanishing linear part `∑_{i∈T} c_i a_i = 0`.
-/
lemma exists_const_combination {n w : ℕ} (H : Arrangement n w) (T : Finset (Fin w))
    (hT : n + 1 ≤ T.card) :
    ∃ c : Fin w → ℝ, (∀ i, i ∉ T → c i = 0) ∧ (∃ i ∈ T, c i ≠ 0) ∧
      ∀ j, ∑ i ∈ T, c i * (H i).1 j = 0 := by
  have h_linear_dep : ¬ LinearIndependent ℝ (fun i : T => (H i).1) := by
    intro h_lin_ind
    have h_card : T.card ≤ n := by
      simpa using linearIndependent_le_basis ( Pi.basisFun ℝ ( Fin n ) ) ( fun i : T => ( H i ).1 ) h_lin_ind;
    grind;
  rw [ Fintype.not_linearIndependent_iff ] at h_linear_dep;
  obtain ⟨ g, hg₁, i, hi ⟩ := h_linear_dep;
  refine' ⟨ fun j => if hj : j ∈ T then g ⟨ j, hj ⟩ else 0, _, _, _ ⟩ <;> simp_all +decide [ funext_iff ];
  · exact ⟨ i, i.2, hi ⟩;
  · convert hg₁ using 1;
    rw [ ← Finset.sum_attach ] ; aesop

/-
**Orthant obstruction.**  If a combination supported on `T` with nonzero coefficient
is constant (equal to `d`) as a function of `x`, then not every sign pattern on `T` is
realizable in the complement: there is a subset `U ⊆ T` such that no point off the
hyperplanes has `T ∩ posSet H x = U`.
-/
lemma exists_unrealizable_subset {n w : ℕ} (H : Arrangement n w) (T : Finset (Fin w))
    (c : Fin w → ℝ) (hne : ∃ i ∈ T, c i ≠ 0) (d : ℝ)
    (hconst : ∀ x, ∑ i ∈ T, c i * affEval (H i) x = d) :
    ∃ U ⊆ T, ∀ x, (∀ i, affEval (H i) x ≠ 0) → T ∩ posSet H x ≠ U := by
  by_cases hd : d ≤ 0;
  · refine' ⟨ T.filter ( fun i => 0 < c i ), _, _ ⟩ <;> simp_all +decide [ Finset.subset_iff ];
    intro x hx h; simp_all +decide [ Finset.ext_iff, posSet ] ;
    -- Since $c_i * affEval (H i) x > 0$ for all $i \in T$, the sum $\sum_{i \in T} c_i * affEval (H i) x$ must be positive.
    have h_sum_pos : 0 < ∑ i ∈ T, c i * affEval (H i) x := by
      apply Finset.sum_pos';
      · intro i hi; specialize h i hi; by_cases hi' : 0 < c i <;> simp_all +decide [ mul_nonneg_iff ] ;
        linarith;
      · obtain ⟨ i, hi, hi' ⟩ := hne;
        cases lt_or_gt_of_ne hi' <;> simp_all +decide [ mul_pos_iff ];
        · exact ⟨ i, hi, Or.inr ⟨ by linarith, lt_of_le_of_ne ( le_of_not_gt fun hi'' => by linarith [ h i hi |>.1 hi'' ] ) ( hx i ) ⟩ ⟩;
        · exact ⟨ i, hi, Or.inl ⟨ by assumption, h i hi |>.2 ‹_› ⟩ ⟩;
    linarith [ hconst x ];
  · refine' ⟨ Finset.filter ( fun i => c i < 0 ) T, _, _ ⟩;
    · exact Finset.filter_subset _ _;
    · intro x hx h; simp_all +decide [ Finset.ext_iff, posSet ] ;
      -- For each $i \in T$, we have $c_i * affEval (H i) x \leq 0$.
      have h_nonpos : ∀ i ∈ T, c i * affEval (H i) x ≤ 0 := by
        intro i hi; specialize h i hi; by_cases hi' : c i < 0 <;> simp_all +decide [ mul_nonpos_iff ] ;
        grobner;
      exact hd.not_ge ( hconst x ▸ Finset.sum_nonpos h_nonpos )

/-- The realizable-sign-vector family of an arrangement of `w` hyperplanes in `ℝ^n` does
not shatter any index set of size `> n`. -/
lemma not_shatters_of_card_gt {n w : ℕ} (H : Arrangement n w) (T : Finset (Fin w))
    (hT : n + 1 ≤ T.card) : ¬ (regionFamily H).Shatters T := by
  obtain ⟨c, hsupp, hne, hlin⟩ := exists_const_combination H T hT
  set d := ∑ i ∈ T, c i * (H i).2 with hd_def
  have hconst : ∀ x, ∑ i ∈ T, c i * affEval (H i) x = d := by
    intro x
    have : ∑ i ∈ T, c i * affEval (H i) x
        = (∑ i ∈ T, c i * (∑ j, (H i).1 j * x j)) + ∑ i ∈ T, c i * (H i).2 := by
      rw [← Finset.sum_add_distrib]
      refine Finset.sum_congr rfl (fun i _ => ?_)
      simp [affEval, mul_add]
    rw [this]
    have hzero : (∑ i ∈ T, c i * (∑ j, (H i).1 j * x j)) = 0 := by
      calc (∑ i ∈ T, c i * (∑ j, (H i).1 j * x j))
          = ∑ i ∈ T, ∑ j, c i * (H i).1 j * x j := by
            refine Finset.sum_congr rfl (fun i _ => ?_)
            rw [Finset.mul_sum]
            refine Finset.sum_congr rfl (fun j _ => ?_); ring
        _ = ∑ j, ∑ i ∈ T, c i * (H i).1 j * x j := Finset.sum_comm
        _ = ∑ j, (∑ i ∈ T, c i * (H i).1 j) * x j := by
            refine Finset.sum_congr rfl (fun j _ => ?_); rw [Finset.sum_mul]
        _ = 0 := by simp [hlin]
    rw [hzero, zero_add]
  obtain ⟨U, hUT, hUbad⟩ := exists_unrealizable_subset H T c hne d hconst
  intro hsh
  obtain ⟨S, hSmem, hSU⟩ := hsh hUT
  obtain ⟨x, hxne, hxS⟩ := (mem_regionFamily H S).1 hSmem
  exact hUbad x hxne (by rw [hxS]; exact hSU)

/-
The VC dimension of the realizable-sign-vector family is at most `n`.
-/
lemma vcDim_le {n w : ℕ} (H : Arrangement n w) : (regionFamily H).vcDim ≤ n := by
  refine' Finset.sup_le fun s hs => _;
  exact le_of_not_gt fun h => not_shatters_of_card_gt H s h <| Finset.mem_shatterer.mp hs

/-
Truncating the upper summation index of `∑ C(w,k)` at `min n w` does not change the
value beyond `min n w` since the binomial coefficients vanish.
-/
lemma sum_choose_Iic_eq {n w : ℕ} :
    ∑ k ∈ Finset.Iic n, w.choose k = ∑ k ∈ Finset.range (min n w + 1), w.choose k := by
  by_cases hn : n ≤ w;
  · rw [ min_eq_left hn, Finset.range_eq_Ico ] ; rfl;
  · rw [ ← Finset.sum_subset ( show Finset.range ( w + 1 ) ⊆ Finset.Iic n from fun x hx => Finset.mem_Iic.mpr <| by linarith [ Finset.mem_range.mp hx ] ) ];
    · rw [ min_eq_right ( le_of_not_ge hn ) ];
    · exact fun x hx₁ hx₂ => Nat.choose_eq_zero_of_lt <| by linarith [ Finset.mem_Iic.mp hx₁, Finset.mem_range.not.mp hx₂ ] ;

/-! ### Theorem 2 : Schläfli's bound -/

/-
**Theorem 2 (Schläfli's hyperplane-arrangement bound).**  A hyperplane arrangement of
`w` hyperplanes in `ℝ^n` has at most `∑_{k=0}^{min n w} C(w,k)` regions.
-/
theorem region_count_bound {n w : ℕ} (H : Arrangement n w) :
    RegionCount H ≤ ∑ k ∈ Finset.range (min n w + 1), w.choose k := by
  rw [← sum_choose_Iic_eq]
  have h1 : (regionFamily H).card ≤ (regionFamily H).shatterer.card :=
    Finset.card_le_card_shatterer _
  have h2 : (regionFamily H).shatterer.card
      ≤ ∑ k ∈ Finset.Iic (regionFamily H).vcDim, (Fintype.card (Fin w)).choose k :=
    Finset.card_shatterer_le_sum_vcDim
  have h3 : ∑ k ∈ Finset.Iic (regionFamily H).vcDim, (Fintype.card (Fin w)).choose k
      ≤ ∑ k ∈ Finset.Iic n, w.choose k := by
    simp only [Fintype.card_fin]
    exact Finset.sum_le_sum_of_subset (Finset.Iic_subset_Iic.mpr (vcDim_le H))
  exact h1.trans (h2.trans h3)

/-! ### Single hidden layer ReLU networks -/

/-- A single hidden layer ReLU network `f(x) = c₀ + ∑ aᵢ · relu(⟨Wᵢ,x⟩ + bᵢ)`. -/
def network {n w : ℕ} (a : Fin w → ℝ) (H : Arrangement n w) (c0 : ℝ) (x : Fin n → ℝ) : ℝ :=
  c0 + ∑ i, a i * relu (affEval (H i) x)

/-
On the chamber `{y : posSet H y = posSet H x}` the network equals the affine map
`c₀ + ∑_{i ∈ posSet H x} aᵢ · (⟨Wᵢ,·⟩ + bᵢ)`.
-/
lemma network_eq_on_region {n w : ℕ} (a : Fin w → ℝ) (H : Arrangement n w) (c0 : ℝ)
    (x : Fin n → ℝ) :
    network a H c0 x = c0 + ∑ i ∈ posSet H x, a i * affEval (H i) x := by
  unfold network;
  rw [ ← Finset.sum_subset ( Finset.subset_univ ( posSet H x ) ) ];
  · exact congrArg _ ( Finset.sum_congr rfl fun i hi => by rw [ mem_posSet ] at hi; rw [ relu_of_pos hi ] );
  · simp +contextual [ posSet, relu ]

/-- **Theorem 3 (Main bound).**  A single hidden layer ReLU network of width `w` on
`ℝ^n` is affine on each chamber of the arrangement of its `w` neuron hyperplanes (first
conjunct), and the number of its linear regions is at most `∑_{k=0}^{min n w} C(w,k)`
(second conjunct). -/
theorem single_layer_region_bound {n w : ℕ} (a : Fin w → ℝ) (H : Arrangement n w)
    (c0 : ℝ) :
    (∀ x : Fin n → ℝ,
        network a H c0 x = c0 + ∑ i ∈ posSet H x, a i * affEval (H i) x) ∧
      RegionCount H ≤ ∑ k ∈ Finset.range (min n w + 1), w.choose k :=
  ⟨network_eq_on_region a H c0, region_count_bound H⟩

/-! ### Deep ReLU networks and a depth-dependent region bound -/

/-
**Theorem 4 (Depth-dependent bound).**

The prompt asks for a bound of the form `∏_{i=1}^{L} w_i^{n · 2^{L-1}}`.  That literal
formula is *false* in general: already for one layer (`L = 1`) it reads `w₁^n`, yet a
single layer of width `w` in `ℝ^n` can realize up to `∑_{k≤min n w} C(w,k)` regions, e.g.
`w = 2, n = 1` gives `3 > 2^1`.  We therefore prove a correct, explicitly
depth-dependent **product** upper bound instead.

We model a depth-`L` ReLU network with layer dimensions `d : ℕ → ℕ` (`d 0` is the input
dimension, `d (t+1)` the width of the `(t+1)`-st layer), weights `W` and biases `b`.  The
*activation pattern* of an input `x` records, layer by layer, which neurons are active
(pre-activation `> 0`); this is the standard combinatorial proxy for the linear region
containing `x`, since the network is affine on each fixed activation pattern.  The number
of linear regions is the number of realizable activation patterns, and it is bounded by
the size of the pattern space `∏_{t<L} 2^{d (t+1)}`.
-/

/-- Forward pass of a deep ReLU network: `forward d W b t x` is the output of layer `t`
on input `x` (layer `0` is the identity input layer; each subsequent layer applies an
affine map followed by coordinatewise ReLU). -/
noncomputable def forward (d : ℕ → ℕ) (W : ∀ t, Fin (d (t + 1)) → Fin (d t) → ℝ)
    (b : ∀ t, Fin (d (t + 1)) → ℝ) : ∀ t, (Fin (d 0) → ℝ) → (Fin (d t) → ℝ)
  | 0, x => x
  | t + 1, x => fun o => relu (affEval (W t o, b t o) (forward d W b t x))

/-- The global activation pattern of an input: for each layer `t < L`, the set of neurons
whose pre-activation is strictly positive. -/
noncomputable def deepPat (d : ℕ → ℕ) (W : ∀ t, Fin (d (t + 1)) → Fin (d t) → ℝ)
    (b : ∀ t, Fin (d (t + 1)) → ℝ) (L : ℕ) :
    (Fin (d 0) → ℝ) → ((t : Fin L) → Finset (Fin (d (t.val + 1)))) :=
  fun x t =>
    Finset.univ.filter (fun o => 0 < affEval (W t.val o, b t.val o) (forward d W b t.val x))

open scoped Classical in
/-- The number of linear regions of a deep ReLU network, counted as the number of
realizable global activation patterns. -/
noncomputable def deepRegionCount (d : ℕ → ℕ) (W : ∀ t, Fin (d (t + 1)) → Fin (d t) → ℝ)
    (b : ∀ t, Fin (d (t + 1)) → ℝ) (L : ℕ) : ℕ :=
  ((Finset.univ : Finset ((t : Fin L) → Finset (Fin (d (t.val + 1))))).filter
    (fun p => ∃ x, deepPat d W b L x = p)).card

/-- **Theorem 4 (Depth-dependent region bound).**  A depth-`L` ReLU network with layer
dimensions `d` has at most `∏_{t<L} 2^{d (t+1)}` linear regions — an explicitly
depth-dependent product bound, exponential in the per-layer widths. -/
theorem deep_region_bound (d : ℕ → ℕ) (W : ∀ t, Fin (d (t + 1)) → Fin (d t) → ℝ)
    (b : ∀ t, Fin (d (t + 1)) → ℝ) (L : ℕ) :
    deepRegionCount d W b L ≤ ∏ t : Fin L, 2 ^ (d (t.val + 1)) := by
  classical
  refine (Finset.card_filter_le _ _).trans ?_
  rw [Finset.card_univ, Fintype.card_pi]
  apply le_of_eq
  apply Finset.prod_congr rfl
  intro t _
  rw [Fintype.card_finset, Fintype.card_fin]

end ReLURegions
